insert into public.doctors (name, slug, department, title, experience_years, fee, summary, bio, expertise, education, available_days, time_slots, images, is_featured) values
('Dr. Omar Hassan', 'dr-omar-hassan', 'cardiology', 'Consultant Cardiologist', 18, 700, 'Heart health, blood pressure and cardiac check-ups with clear, calm explanations.', 'Dr. Omar leads our cardiology clinic. He focuses on prevention, hypertension and long-term heart care, and spends time making sure every patient understands their results and their plan.', array['Hypertension','Echocardiography','Heart failure care','Cardiac check-ups'], array['MD Cardiology, Cairo University','Fellowship in Interventional Cardiology'], array['Sunday','Tuesday','Thursday'], array['16:00','16:30','17:00','17:30','18:00','18:30','19:00'], array['https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1758691462123-8a17ae95d203?auto=format&fit=crop&w=1000&q=80'], true),
('Dr. Salma Adel', 'dr-salma-adel', 'pediatrics', 'Consultant Pediatrician', 12, 500, 'Gentle care for babies, children and teenagers, from vaccines to growth follow-up.', 'Dr. Salma makes every visit easy for children and parents. She covers newborn care, vaccination schedules, nutrition and common childhood illnesses.', array['Newborn care','Vaccinations','Child nutrition','Growth follow-up'], array['MD Pediatrics, Ain Shams University','Diploma in Neonatology'], array['Saturday','Monday','Wednesday'], array['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30'], array['https://images.unsplash.com/photo-1638202993928-7267aad84c31?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1632053002928-1919605ee6f7?auto=format&fit=crop&w=1000&q=80'], true),
('Dr. Karim Nabil', 'dr-karim-nabil', 'dentistry', 'Cosmetic and General Dentist', 10, 450, 'Pain-free dentistry, whitening, veneers and routine care in a relaxed setting.', 'Dr. Karim combines modern techniques with a gentle approach. He treats nervous patients with patience and plans every smile makeover step by step.', array['Teeth whitening','Veneers','Root canal','Dental implants'], array['BDS, Alexandria University','Master in Cosmetic Dentistry'], array['Sunday','Monday','Wednesday','Thursday'], array['10:00','10:30','11:00','11:30','13:00','13:30','14:00','14:30'], array['https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1681939282781-341ac4f61996?auto=format&fit=crop&w=1000&q=80'], true),
('Dr. Mariam Youssef', 'dr-mariam-youssef', 'dermatology', 'Consultant Dermatologist', 9, 600, 'Skin, hair and nail care, from acne and allergies to modern skin treatments.', 'Dr. Mariam treats medical and cosmetic skin concerns with evidence-based plans. She explains every option so you can choose with confidence.', array['Acne care','Skin allergies','Hair loss','Laser treatments'], array['MD Dermatology, Mansoura University','Fellowship in Laser Dermatology'], array['Saturday','Tuesday','Thursday'], array['10:00','10:30','11:00','11:30','13:00','13:30','14:00','14:30'], array['https://images.unsplash.com/photo-1594824476967-48c8b964273f?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1761718209708-9ab9ba1c7252?auto=format&fit=crop&w=1000&q=80'], true),
('Dr. Youssef Ibrahim', 'dr-youssef-ibrahim', 'orthopedics', 'Consultant Orthopedic Surgeon', 15, 650, 'Bone, joint and sports injury care with a strong focus on getting you moving again.', 'Dr. Youssef treats fractures, joint pain and sports injuries. He prefers the least invasive option that works and plans recovery with each patient.', array['Sports injuries','Knee and shoulder care','Fracture treatment','Joint replacement'], array['MD Orthopedics, Cairo University','Fellowship in Sports Medicine'], array['Sunday','Wednesday','Thursday'], array['16:00','16:30','17:00','17:30','18:00','18:30','19:00'], array['https://images.unsplash.com/photo-1712215544003-af10130f8eb3?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1649751361457-01d3a696c7e6?auto=format&fit=crop&w=1000&q=80'], false),
('Dr. Laila Mahmoud', 'dr-laila-mahmoud', 'ophthalmology', 'Consultant Ophthalmologist', 11, 550, 'Eye exams, vision correction and care for common eye conditions.', 'Dr. Laila handles routine eye exams, vision problems and eye diseases for all ages, with advanced diagnostic equipment and clear advice.', array['Vision tests','Cataract care','Dry eye','Glasses and lenses'], array['MD Ophthalmology, Cairo University','Fellowship in Cornea and Refractive Surgery'], array['Saturday','Monday','Wednesday'], array['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30'], array['https://images.unsplash.com/photo-1659353888906-adb3e0041693?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1758656321505-95bf802f9a4c?auto=format&fit=crop&w=1000&q=80'], false),
('Dr. Hana Samir', 'dr-hana-samir', 'pediatrics', 'Pediatric Specialist', 7, 400, 'Friendly child check-ups, fever and infection care, and advice for new parents.', 'Dr. Hana loves helping new parents feel confident. She sees children for check-ups, infections, allergies and development questions.', array['Child check-ups','Allergies','Infections','New parent advice'], array['MSc Pediatrics, Tanta University'], array['Sunday','Tuesday','Thursday'], array['10:00','10:30','11:00','11:30','13:00','13:30','14:00','14:30'], array['https://images.unsplash.com/photo-1584432810601-6c7f27d2362b?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1758691463331-2ac00e6f676f?auto=format&fit=crop&w=1000&q=80'], false),
('Dr. Tarek Mansour', 'dr-tarek-mansour', 'cardiology', 'Cardiology Specialist', 8, 500, 'Heart screening, ECG and follow-up care for patients of all ages.', 'Dr. Tarek focuses on early detection and day-to-day heart care, including ECG, stress testing and ongoing medication plans.', array['ECG and stress test','Cholesterol','Palpitations','Post-treatment follow-up'], array['MSc Cardiology, Ain Shams University'], array['Saturday','Monday','Wednesday'], array['09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30'], array['https://images.unsplash.com/photo-1758691463582-11aea602cd4a?auto=format&fit=crop&w=1000&q=80', 'https://images.unsplash.com/photo-1758691462353-36b215702253?auto=format&fit=crop&w=1000&q=80'], false)
